public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // ArgumentOutOfRangeException 이 나야 통과
    static string MustThrow(string what, System.Action a)
    {
        try { a(); }
        catch (System.ArgumentOutOfRangeException) { return null; }
        catch (System.Exception e) { return what + ": ArgumentOutOfRangeException 대신 " + e.GetType().Name; }
        return what + ": 예외가 발생하지 않음";
    }

    static string Same(MyList<int> got, System.Collections.Generic.List<int> exp, string ctx)
    {
        if (got.Count != exp.Count) return ctx + ": Count 기대 " + exp.Count + " / 결과 " + got.Count;
        for (int i = 0; i < exp.Count; i++)
            if (got[i] != exp[i]) return ctx + ": [" + i + "] 기대 " + exp[i] + " / 결과 " + got[i];
        return null;
    }

    static MyList<int> Make(params int[] xs)
    {
        var l = new MyList<int>();
        foreach (int x in xs) l.Add(x);
        return l;
    }

    static System.Collections.Generic.List<int> L(params int[] xs) { return new System.Collections.Generic.List<int>(xs); }

    public static void Main()
    {
        Run("add-and-index", () =>
        {
            var l = new MyList<int>();
            if (l.Count != 0) return "빈 리스트의 Count 가 0 이 아님";
            for (int i = 0; i < 10; i++) l.Add(i * 3);
            string e = Same(l, L(0, 3, 6, 9, 12, 15, 18, 21, 24, 27), "Add 10회");
            if (e != null) return e;
            l[4] = -7; l[0] = 100; l[9] = 99;
            return Same(l, L(100, 3, 6, 9, -7, 15, 18, 21, 24, 99), "인덱서 set 후");
        });

        Run("capacity-doubling", () =>
        {
            var l = new MyList<int>();
            if (l.Capacity != 0) return "new MyList() 의 Capacity 기대 0 / 결과 " + l.Capacity;
            int[] expect = { 4, 4, 4, 4, 8, 8, 8, 8, 16, 16, 16, 16, 16, 16, 16, 16, 32 };
            for (int i = 0; i < expect.Length; i++)
            {
                l.Add(i);
                if (l.Capacity != expect[i]) return "Add " + (i + 1) + "회 후 Capacity 기대 " + expect[i] + " / 결과 " + l.Capacity;
            }
            var m = new MyList<int>(3);
            if (m.Capacity != 3 || m.Count != 0) return "new MyList(3): Capacity 3, Count 0 이어야 함 (결과 " + m.Capacity + ", " + m.Count + ")";
            m.Add(1); m.Add(2); m.Add(3);
            if (m.Capacity != 3) return "용량 3 에 3개: 아직 늘리면 안 됨 (결과 " + m.Capacity + ")";
            m.Add(4);
            if (m.Capacity != 6) return "용량 3 에서 4번째 Add: Capacity 기대 6 / 결과 " + m.Capacity;
            var z = new MyList<int>(0);
            z.Add(5);
            if (z.Capacity != 4 || z[0] != 5) return "new MyList(0) 뒤 Add: Capacity 기대 4 / 결과 " + z.Capacity;
            for (int i = 0; i < 17; i++) l.RemoveAt(l.Count - 1);
            return l.Capacity == 32 ? null : "RemoveAt 으로 Capacity 가 줄어듦 (결과 " + l.Capacity + ")";
        });

        Run("bounds-checks", () =>
        {
            var l = Make(10, 20);   // Count 2, Capacity 4
            int sink = 0;
            string err = MustThrow("get [-1]", () => sink = l[-1])
                ?? MustThrow("get [Count] (Count 2, Capacity 4 일 때 [2])", () => sink = l[2])
                ?? MustThrow("set [Count]", () => l[2] = 1)
                ?? MustThrow("set [-1]", () => l[-1] = 1)
                ?? MustThrow("Insert(-1)", () => l.Insert(-1, 0))
                ?? MustThrow("Insert(Count + 1)", () => l.Insert(3, 0))
                ?? MustThrow("RemoveAt(Count)", () => l.RemoveAt(2))
                ?? MustThrow("RemoveAt(-1)", () => l.RemoveAt(-1))
                ?? MustThrow("빈 리스트 get [0]", () => sink = new MyList<int>()[0])
                ?? MustThrow("빈 리스트 RemoveAt(0)", () => new MyList<int>().RemoveAt(0))
                ?? MustThrow("new MyList(-1)", () => new MyList<int>(-1))
                ?? Same(l, L(10, 20), "예외가 난 호출 뒤 내용이 바뀜");
            return err ?? (sink == 0 ? null : "예외 대신 값을 반환함");
        });

        Run("insert-shift", () =>
        {
            var l = Make(1, 2, 3);
            l.Insert(0, 9);                 // 맨 앞. Count 4 = Capacity 4
            string e = Same(l, L(9, 1, 2, 3), "[1,2,3] 에 Insert(0, 9)");
            if (e != null) return e;
            l.Insert(2, 8);                 // 가운데 + 용량 증가
            e = Same(l, L(9, 1, 8, 2, 3), "가득 찬 [9,1,2,3] 에 Insert(2, 8)");
            if (e != null) return e;
            if (l.Capacity != 8) return "가득 찬 상태에서 Insert: Capacity 기대 8 / 결과 " + l.Capacity;
            l.Insert(l.Count, 7);           // index == Count
            e = Same(l, L(9, 1, 8, 2, 3, 7), "Insert(Count, 7)");
            if (e != null) return e;
            var empty = new MyList<int>();
            empty.Insert(0, 5);
            return Same(empty, L(5), "빈 리스트에 Insert(0, 5)");
        });

        Run("remove-shift", () =>
        {
            var l = Make(1, 2, 3, 4, 5);
            l.RemoveAt(0);
            string e = Same(l, L(2, 3, 4, 5), "[1,2,3,4,5] 에서 RemoveAt(0)");
            if (e != null) return e;
            l.RemoveAt(1);
            e = Same(l, L(2, 4, 5), "[2,3,4,5] 에서 RemoveAt(1)");
            if (e != null) return e;
            l.RemoveAt(l.Count - 1);
            e = Same(l, L(2, 4), "마지막 원소 RemoveAt");
            if (e != null) return e;
            l.RemoveAt(0); l.RemoveAt(0);
            if (l.Count != 0) return "전부 지운 뒤 Count 가 0 이 아님";
            l.Add(42);
            return Same(l, L(42), "전부 지운 뒤 Add(42)");
        });

        Run("reference-type", () =>
        {
            var s = new MyList<string>();
            s.Add("sword"); s.Add(null); s.Add("bow");
            s.Insert(1, "shield");
            s.RemoveAt(0);
            if (s.Count != 3) return "MyList<string> Count 기대 3 / 결과 " + s.Count;
            if (s[0] != "shield" || s[1] != null || s[2] != "bow") return "MyList<string> 내용이 [shield, null, bow] 가 아님";
            return null;
        });

        Run("random-vs-list", () =>
        {
            var rng = new System.Random(20240501);
            var mine = new MyList<int>();
            var exp = new System.Collections.Generic.List<int>();
            for (int step = 0; step < 20000; step++)
            {
                int op = rng.Next(100), v = rng.Next(-1000, 1000);
                if (op < 35) { mine.Add(v); exp.Add(v); }
                else if (op < 60) { int i = rng.Next(exp.Count + 1); mine.Insert(i, v); exp.Insert(i, v); }
                else if (op < 90 && exp.Count > 0) { int i = rng.Next(exp.Count); mine.RemoveAt(i); exp.RemoveAt(i); }
                else if (exp.Count > 0) { int i = rng.Next(exp.Count); mine[i] = v; exp[i] = v; }
                if (step % 97 == 0 || mine.Count != exp.Count)
                {
                    string e = Same(mine, exp, step + "번째 연산 후");
                    if (e != null) return e;
                }
            }
            return Same(mine, exp, "마지막");
        });

        Run("large-append", () =>
        {
            const int N = 300000;
            var l = new MyList<int>();
            for (int i = 0; i < N; i++)
            {
                l.Add(i);
                if (i == 4999 && l.Capacity != 8192) return "Add 5000회 후 Capacity 기대 8192 / 결과 " + l.Capacity;
            }
            if (l.Count != N) return "Add " + N + "회 후 Count 결과 " + l.Count;
            if (l.Capacity != 524288) return "Add " + N + "회 후 Capacity 기대 524288 / 결과 " + l.Capacity;
            long sum = 0;
            for (int i = 0; i < N; i++) sum += l[i];
            return sum == (long)N * (N - 1) / 2 ? null : "Add " + N + "회 후 원소 합이 다름";
        });
    }
}

