problems.solutionCode:
#include <cstddef>
#include <vector>

// 고정 용량 링 버퍼. 가득 찬 상태에서 push 하면 가장 오래된 값을 덮어쓴다.
class InputRingBuffer {
public:
    // capacity >= 1 이라고 가정한다. 메모리는 여기서 한 번만 잡는다.
    explicit InputRingBuffer(std::size_t capacity)
        : buf_(capacity), head_(0), count_(0) {}

    std::size_t capacity() const { return buf_.size(); }
    std::size_t size() const { return count_; }
    bool empty() const { return count_ == 0; }
    bool full() const { return count_ == buf_.size(); }

    bool push(int value) {
        if (full()) {
            // head_ 가 가리키는 칸이 가장 오래된 값이자, 한 바퀴 돈 tail 의 위치다.
            buf_[head_] = value;
            head_ = next(head_);
            return true;                // 덮어썼다
        }
        buf_[wrap(head_ + count_)] = value;
        ++count_;
        return false;
    }

    bool pop(int& out) {
        if (empty()) return false;
        out = buf_[head_];
        head_ = next(head_);
        --count_;
        return true;
    }

    bool front(int& out) const {
        if (empty()) return false;
        out = buf_[head_];
        return true;
    }

    bool at(std::size_t i, int& out) const {
        if (i >= count_) return false;
        out = buf_[wrap(head_ + i)];
        return true;
    }

private:
    // head_ < capacity, i <= capacity 이므로 합은 2 * capacity 미만이다.
    std::size_t wrap(std::size_t i) const { return i % buf_.size(); }
    std::size_t next(std::size_t i) const { return wrap(i + 1); }

    std::vector<int> buf_;
    std::size_t head_;      // 가장 오래된 원소의 인덱스
    std::size_t count_;     // 들어 있는 원소 수
};

