public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static string Has(IntHashMap m, int key, int expected)
    {
        int v;
        if (!m.TryGet(key, out v)) return "TryGet(" + key + ") 기대 true(" + expected + ") / 결과 false";
        return v == expected ? null : "TryGet(" + key + ") 기대 " + expected + " / 결과 " + v;
    }

    static string Missing(IntHashMap m, int key)
    {
        int v;
        if (m.TryGet(key, out v)) return "TryGet(" + key + ") 기대 false / 결과 true(" + v + ")";
        return v == 0 ? null : "TryGet(" + key + ") 실패 시 value 기대 0 / 결과 " + v;
    }

    static string CountIs(IntHashMap m, int expected, string ctx)
    {
        return m.Count == expected ? null : ctx + ": Count 기대 " + expected + " / 결과 " + m.Count;
    }

    public static void Main()
    {
        Run("put-get-basic", () =>
        {
            var m = new IntHashMap();
            string e = CountIs(m, 0, "빈 테이블") ?? Missing(m, 1001);
            if (e != null) return e;
            m.Put(1001, 3); m.Put(1002, 1); m.Put(7, 99);
            return CountIs(m, 3, "Put 3회") ?? Has(m, 1001, 3) ?? Has(m, 1002, 1) ?? Has(m, 7, 99) ?? Missing(m, 1003);
        });

        Run("update-existing", () =>
        {
            var m = new IntHashMap();
            m.Put(5, 1); m.Put(5, 2); m.Put(13, 7); m.Put(5, 30); m.Put(13, 0);
            return CountIs(m, 2, "같은 키를 여러 번 Put") ?? Has(m, 5, 30) ?? Has(m, 13, 0);
        });

        Run("negative-keys", () =>
        {
            var m = new IntHashMap();
            int[] keys = { -1, -8, -9, 0, int.MinValue, int.MaxValue };
            for (int i = 0; i < keys.Length; i++) m.Put(keys[i], i + 1);
            string e = CountIs(m, keys.Length, "키 [-1, -8, -9, 0, int.MinValue, int.MaxValue] Put");
            for (int i = 0; e == null && i < keys.Length; i++) e = Has(m, keys[i], i + 1);
            if (e != null) return e;
            if (!m.Remove(int.MinValue)) return "Remove(int.MinValue) 기대 true / 결과 false";
            if (!m.Remove(-1)) return "Remove(-1) 기대 true / 결과 false";
            return Missing(m, int.MinValue) ?? Missing(m, -1) ?? Has(m, -8, 2) ?? Has(m, -9, 3) ?? Missing(m, 1) ?? Missing(m, 8);
        });

        Run("collision-chain", () =>
        {
            // 버킷 8개에서 나머지 연산으로는 모두 같은 버킷에 떨어지는 키들 (1024 의 배수)
            var m = new IntHashMap();
            int[] keys = { 0, 1024, 2048, -1024, 4096 };
            for (int i = 0; i < keys.Length; i++) m.Put(keys[i], 10 + i);
            string e = CountIs(m, 5, "키 [0, 1024, 2048, -1024, 4096] Put");
            for (int i = 0; e == null && i < keys.Length; i++) e = Has(m, keys[i], 10 + i);
            if (e != null) return e;
            m.Put(2048, 77);
            e = CountIs(m, 5, "충돌 체인 안의 키 갱신") ?? Has(m, 2048, 77);
            if (e != null) return e;
            if (!m.Remove(2048)) return "Remove(2048) 기대 true / 결과 false";
            e = Missing(m, 2048) ?? Has(m, 0, 10) ?? Has(m, 1024, 11) ?? Has(m, -1024, 13) ?? Has(m, 4096, 14);
            if (e != null) return "Remove(2048) 후 " + e;
            if (!m.Remove(0) || !m.Remove(4096)) return "Remove(0), Remove(4096) 기대 true";
            e = CountIs(m, 2, "3개 제거 후") ?? Has(m, 1024, 11) ?? Has(m, -1024, 13) ?? Missing(m, 0) ?? Missing(m, 4096);
            return e == null ? null : "Remove(0), Remove(4096) 후 " + e;
        });

        Run("remove", () =>
        {
            var m = new IntHashMap();
            if (m.Remove(3)) return "빈 테이블에서 Remove(3) 기대 false / 결과 true";
            m.Put(3, 30); m.Put(4, 40);
            if (m.Remove(5)) return "없는 키 Remove(5) 기대 false / 결과 true";
            string e = CountIs(m, 2, "없는 키 Remove 후");
            if (e != null) return e;
            if (!m.Remove(3)) return "Remove(3) 기대 true / 결과 false";
            e = CountIs(m, 1, "Remove(3) 후") ?? Missing(m, 3) ?? Has(m, 4, 40);
            if (e != null) return e;
            if (m.Remove(3)) return "이미 지운 키 Remove(3) 기대 false / 결과 true";
            m.Put(3, 31);
            return CountIs(m, 2, "지운 키를 다시 Put") ?? Has(m, 3, 31);
        });

        Run("resize-load-factor", () =>
        {
            var m = new IntHashMap();
            if (m.BucketCount != 8) return "처음 BucketCount 기대 8 / 결과 " + m.BucketCount;
            for (int i = 1; i <= 25; i++)
            {
                m.Put(i * 37 - 400, i);
                int expect = i <= 6 ? 8 : i <= 12 ? 16 : i <= 24 ? 32 : 64;
                if (m.BucketCount != expect) return "새 키 " + i + "개째 Put 후 BucketCount 기대 " + expect + " / 결과 " + m.BucketCount;
            }
            for (int i = 1; i <= 25; i++)
            {
                string e = Has(m, i * 37 - 400, i);
                if (e != null) return "리사이즈 후 " + e;
            }
            m.Put(37 - 400, 500);
            if (m.BucketCount != 64 || m.Count != 25) return "기존 키 갱신으로 Count 또는 BucketCount 가 바뀜";
            for (int i = 1; i <= 25; i++) m.Remove(i * 37 - 400);
            if (m.Count != 0) return "전부 Remove 후 Count 결과 " + m.Count;
            return m.BucketCount == 64 ? null : "Remove 로 BucketCount 가 줄어듦 (결과 " + m.BucketCount + ")";
        });

        Run("random-vs-dictionary", () =>
        {
            var rng = new System.Random(987654);
            var m = new IntHashMap();
            var exp = new System.Collections.Generic.Dictionary<int, int>();
            for (int step = 0; step < 30000; step++)
            {
                int k = rng.Next(100);
                int key = k < 50 ? rng.Next(-40, 41) : k < 80 ? rng.Next(-30, 31) * 64 : rng.Next(int.MinValue, int.MaxValue);
                int op = rng.Next(100);
                if (op < 45)
                {
                    int v = rng.Next(1, 1000);
                    m.Put(key, v); exp[key] = v;
                }
                else if (op < 70)
                {
                    bool a = m.Remove(key), b = exp.Remove(key);
                    if (a != b) return step + "번째 연산 Remove(" + key + ") 기대 " + b + " / 결과 " + a;
                }
                else
                {
                    int v;
                    string e = exp.TryGetValue(key, out v) ? Has(m, key, v) : Missing(m, key);
                    if (e != null) return step + "번째 연산 " + e;
                }
                if (m.Count != exp.Count) return step + "번째 연산 후 Count 기대 " + exp.Count + " / 결과 " + m.Count;
            }
            foreach (var kv in exp)
            {
                string e = Has(m, kv.Key, kv.Value);
                if (e != null) return "마지막 전수 검사 " + e;
            }
            return null;
        });

        Run("large-rehash", () =>
        {
            const int N = 200000;
            var m = new IntHashMap();
            for (int i = 0; i < N; i++)
            {
                m.Put(i * 7919 - 700000000, i);
                if (i == 4999 && m.BucketCount != 8192) return "서로 다른 키 5000개 Put 후 BucketCount 기대 8192 / 결과 " + m.BucketCount;
            }
            string e = CountIs(m, N, "서로 다른 키 " + N + "개 Put");
            if (e != null) return e;
            if (m.BucketCount != 524288) return N + "개 Put 후 BucketCount 기대 524288 / 결과 " + m.BucketCount;
            for (int i = 0; i < N; i += 7)
            {
                e = Has(m, i * 7919 - 700000000, i);
                if (e != null) return e;
            }
            return Missing(m, 123456789);
        });
    }
}

