public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    // 스크립트: "S x y t" = SetTile, "U" = Undo, "R" = Redo. 3x3 맵에서 실행한다.
    // 반환: Undo/Redo 의 반환값(T/F) 나열 + " | " + 타일 9칸(x 우선) + " | " + UndoCount + "/" + RedoCount
    static string Play(string script)
    {
        var h = new LevelEditorHistory(3, 3);
        var sb = new System.Text.StringBuilder();
        foreach (string raw in script.Split(';'))
        {
            string[] t = raw.Trim().Split(' ');
            if (t[0] == "S") h.SetTile(int.Parse(t[1]), int.Parse(t[2]), int.Parse(t[3]));
            else if (t[0] == "U") sb.Append(h.Undo() ? 'T' : 'F');
            else if (t[0] == "R") sb.Append(h.Redo() ? 'T' : 'F');
        }
        sb.Append(" | ");
        for (int x = 0; x < 3; x++) for (int y = 0; y < 3; y++) sb.Append(h.GetTile(x, y));
        sb.Append(" | ").Append(h.UndoCount).Append('/').Append(h.RedoCount);
        return sb.ToString();
    }

    static string Expect(string script, string expected)
    {
        string got = Play(script);
        return got == expected ? null : "입력 [" + script + "] 기대 [" + expected + "] / 결과 [" + got + "] (형식: Undo·Redo 반환값 | 타일 9칸 | UndoCount/RedoCount)";
    }

    public static void Main()
    {
        Run("basic-undo", () =>
            Expect("S 0 0 1", " | 100000000 | 1/0")
            ?? Expect("S 0 0 1; U", "T | 000000000 | 0/1")
            ?? Expect("S 0 0 1; S 0 1 2; S 0 0 3; U", "T | 120000000 | 2/1")
            ?? Expect("S 0 0 1; S 0 1 2; S 0 0 3; U; U; U", "TTT | 000000000 | 0/3"));

        Run("undo-redo-empty", () =>
            Expect("U", "F | 000000000 | 0/0")
            ?? Expect("R", "F | 000000000 | 0/0")
            ?? Expect("S 1 1 4; U; U", "TF | 000000000 | 0/1")
            ?? Expect("S 1 1 4; U; R; R", "TTF | 000040000 | 1/0"));

        Run("redo-restores", () =>
            Expect("S 0 0 1; U; R", "TT | 100000000 | 1/0")
            ?? Expect("S 0 0 1; S 2 2 5; U; U; R", "TTT | 100000000 | 1/1")
            ?? Expect("S 0 0 1; S 2 2 5; U; U; R; R", "TTTT | 100000005 | 2/0"));

        Run("undo-after-redo", () =>
            Expect("S 0 0 1; U; R; U", "TTT | 000000000 | 0/1")
            ?? Expect("S 0 0 1; S 0 0 2; U; U; R; R; U", "TTTTT | 100000000 | 1/1")
            ?? Expect("S 0 0 1; S 0 0 2; U; R; U; R; U; U", "TTTTTT | 000000000 | 0/2"));

        Run("new-edit-clears-redo", () =>
            Expect("S 0 0 1; U; S 1 1 5; R", "TF | 000050000 | 1/0")
            ?? Expect("S 0 0 1; S 0 0 2; S 0 0 3; U; U; S 2 0 7; R; U; U", "TTFTT | 000000000 | 0/2"));

        Run("noop-edit-keeps-history", () =>
            Expect("S 0 0 0", " | 000000000 | 0/0")
            ?? Expect("S 0 0 1; S 0 0 1", " | 100000000 | 1/0")
            ?? Expect("S 0 0 1; U; S 0 0 0", "T | 000000000 | 0/1"));

        Run("random-vs-snapshots", () =>
        {
            // 기준 모델: 편집마다 맵 전체를 복사해 둔 스냅숏 목록 + 현재 위치
            var rng = new System.Random(4242);
            for (int round = 0; round < 40; round++)
            {
                var h = new LevelEditorHistory(3, 3);
                var snaps = new System.Collections.Generic.List<int[]>();
                snaps.Add(new int[9]);
                int cur = 0;
                var log = new System.Text.StringBuilder();
                for (int step = 0; step < 60; step++)
                {
                    int op = rng.Next(10);
                    bool got = true, exp = true;
                    if (op < 5)
                    {
                        int x = rng.Next(3), y = rng.Next(3), t = rng.Next(3);
                        log.Append("S ").Append(x).Append(' ').Append(y).Append(' ').Append(t).Append("; ");
                        h.SetTile(x, y, t);
                        if (snaps[cur][x * 3 + y] != t)
                        {
                            snaps.RemoveRange(cur + 1, snaps.Count - cur - 1);
                            int[] next = (int[])snaps[cur].Clone();
                            next[x * 3 + y] = t;
                            snaps.Add(next);
                            cur++;
                        }
                    }
                    else if (op < 8) { log.Append("U; "); got = h.Undo(); exp = cur > 0; if (exp) cur--; }
                    else { log.Append("R; "); got = h.Redo(); exp = cur < snaps.Count - 1; if (exp) cur++; }

                    string where = "입력 [" + (log.Length > 150 ? "... " + log.ToString(log.Length - 150, 150) : log.ToString()) + "] 의 마지막 연산 뒤: ";
                    if (got != exp) return where + "반환값 기대 " + exp + " / 결과 " + got;
                    for (int i = 0; i < 9; i++)
                        if (h.GetTile(i / 3, i % 3) != snaps[cur][i])
                            return where + "타일 (" + (i / 3) + "," + (i % 3) + ") 기대 " + snaps[cur][i] + " / 결과 " + h.GetTile(i / 3, i % 3);
                    if (h.UndoCount != cur || h.RedoCount != snaps.Count - 1 - cur)
                        return where + "UndoCount/RedoCount 기대 " + cur + "/" + (snaps.Count - 1 - cur) + " / 결과 " + h.UndoCount + "/" + h.RedoCount;
                }
            }
            return null;
        });
    }
}

