using System;
using System.Collections.Generic;

// 중복 없는 int 점수를 담는 이진 탐색 트리(균형 없음).
public sealed class ScoreTree
{
    private sealed class Node
    {
        public int Key;
        public Node Left, Right;
        public Node(int key) { Key = key; }
    }

    private Node _root;

    public int Count { get; private set; }

    public bool Insert(int score)
    {
        if (_root == null)
        {
            _root = new Node(score);
            Count = 1;
            return true;
        }

        Node cur = _root;
        while (true)
        {
            if (score == cur.Key) return false; // 중복은 무시
            if (score < cur.Key)
            {
                if (cur.Left == null) { cur.Left = new Node(score); break; }
                cur = cur.Left;
            }
            else
            {
                if (cur.Right == null) { cur.Right = new Node(score); break; }
                cur = cur.Right;
            }
        }
        Count++;
        return true;
    }

    public bool Contains(int score)
    {
        Node cur = _root;
        while (cur != null)
        {
            if (score == cur.Key) return true;
            cur = score < cur.Key ? cur.Left : cur.Right;
        }
        return false;
    }

    public bool Remove(int score)
    {
        // 1) 지울 노드와 그 부모를 찾는다.
        Node parent = null, cur = _root;
        while (cur != null && cur.Key != score)
        {
            parent = cur;
            cur = score < cur.Key ? cur.Left : cur.Right;
        }
        if (cur == null) return false;

        // 2) 자식이 둘이면 중위 후속자(오른쪽 서브트리의 최솟값)의 키를 복사해 오고,
        //    실제로 떼어낼 대상을 후속자 노드로 바꾼다. 후속자에게는 왼쪽 자식이 없다.
        if (cur.Left != null && cur.Right != null)
        {
            Node succParent = cur, succ = cur.Right;
            while (succ.Left != null)
            {
                succParent = succ;
                succ = succ.Left;
            }
            cur.Key = succ.Key;
            parent = succParent;
            cur = succ;
        }

        // 3) 이제 cur 의 자식은 0개 또는 1개다. 그 자식(없으면 null)을 부모에 이어 붙인다.
        Node child = cur.Left != null ? cur.Left : cur.Right;
        if (parent == null) _root = child;
        else if (parent.Left == cur) parent.Left = child;
        else parent.Right = child;

        Count--;
        return true;
    }

    public void InOrder(List<int> results)
    {
        results.Clear();
        // 정렬된 입력에서는 깊이가 n 이 되므로 재귀 대신 명시적 스택을 쓴다.
        var stack = new Stack<Node>();
        Node cur = _root;
        while (cur != null || stack.Count > 0)
        {
            while (cur != null)
            {
                stack.Push(cur);
                cur = cur.Left;
            }
            cur = stack.Pop();
            results.Add(cur.Key);
            cur = cur.Right;
        }
    }
}

