using System;
using System.Collections.Generic;

public static class TileRegions
{
    private static readonly int[] DRow = { -1, 1, 0, 0 };
    private static readonly int[] DCol = { 0, 0, -1, 1 };

    public static int CountRegions(bool[,] walkable, out int largestSize)
    {
        int rows = walkable.GetLength(0), cols = walkable.GetLength(1);
        largestSize = 0;
        int regions = 0;

        var visited = new bool[rows, cols]; // 입력을 건드리지 않기 위한 별도 표시
        var stack = new Stack<int>();       // 칸 번호 = row * cols + col

        for (int r = 0; r < rows; r++)
        {
            for (int c = 0; c < cols; c++)
            {
                if (!walkable[r, c] || visited[r, c]) continue;

                // 아직 어느 구역에도 속하지 않은 칸: 새 구역의 시작점
                regions++;
                int size = 0;
                visited[r, c] = true;
                stack.Push(r * cols + c);

                while (stack.Count > 0)
                {
                    int cell = stack.Pop();
                    int row = cell / cols, col = cell % cols;
                    size++;

                    for (int d = 0; d < 4; d++)
                    {
                        int nr = row + DRow[d], nc = col + DCol[d];
                        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
                        if (!walkable[nr, nc] || visited[nr, nc]) continue;
                        visited[nr, nc] = true;  // 넣는 시점에 표시: 한 칸은 한 번만 들어간다
                        stack.Push(nr * cols + nc);
                    }
                }

                if (size > largestSize) largestSize = size;
            }
        }
        return regions;
    }
}

