using System;

public struct RankEntry
{
    public int PlayerId;
    public int Score;
}

public static class RankingSorter
{
    // entries 를 제자리에서 정렬한다: Score 내림차순, Score 가 같으면 입력 순서 유지(안정 정렬).
    public static void SortByScoreDescending(RankEntry[] entries)
    {
        if (entries.Length < 2) return;
        var buffer = new RankEntry[entries.Length]; // 보조 배열은 한 번만 할당해 재귀 전체가 공유한다
        MergeSort(entries, buffer, 0, entries.Length);
    }

    // 반열린 구간 [lo, hi) 를 정렬한다.
    private static void MergeSort(RankEntry[] a, RankEntry[] buffer, int lo, int hi)
    {
        if (hi - lo < 2) return;
        int mid = lo + (hi - lo) / 2;
        MergeSort(a, buffer, lo, mid);
        MergeSort(a, buffer, mid, hi);
        if (a[mid - 1].Score >= a[mid].Score) return; // 두 절반이 이미 이어져 있으면 병합 생략
        Merge(a, buffer, lo, mid, hi);
    }

    private static void Merge(RankEntry[] a, RankEntry[] buffer, int lo, int mid, int hi)
    {
        int i = lo, j = mid, k = lo;
        while (i < mid && j < hi)
        {
            // 오른쪽이 "엄격히" 더 클 때만 오른쪽을 먼저 꺼낸다.
            // 동점이면 왼쪽(원래 앞에 있던 쪽)이 먼저 나가므로 안정성이 유지된다.
            if (a[j].Score > a[i].Score) buffer[k++] = a[j++];
            else buffer[k++] = a[i++];
        }
        while (i < mid) buffer[k++] = a[i++];
        while (j < hi) buffer[k++] = a[j++];
        Array.Copy(buffer, lo, a, lo, hi - lo);
    }
}

