using System;

public static class ComboAnalyzer
{
    // damages[i] >= 0, target >= 1.
    // 반환: 합이 target 이상인 연속 구간의 최소 길이(타수). 그런 구간이 없으면 0.
    public static int MinHitsToReach(int[] damages, long target)
    {
        int best = int.MaxValue;
        int left = 0;
        long sum = 0; // 창 [left, right] 의 합. int 로 더하면 넘칠 수 있으므로 long.

        for (int right = 0; right < damages.Length; right++)
        {
            sum += damages[right];

            // right 를 끝으로 하는 창 가운데 조건을 만족하는 가장 짧은 것까지 왼쪽을 줄인다.
            // target >= 1 이므로 창이 비면(sum == 0) 반드시 멈춘다.
            while (sum >= target)
            {
                int length = right - left + 1;
                if (length < best) best = length;
                sum -= damages[left];
                left++;
            }
        }

        return best == int.MaxValue ? 0 : best;
    }
}

