    static void Report(string id, string err)
    {
        lock (Gate)
        {
            if (!Reported.Add(id)) return;
            System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
        }
    }

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        Report(id, err);
    }

    // 학습자 코드가 끝나지 않아도 채점이 멈추지 않도록 별도 스레드에서 실행하고 제한 시간을 둔다.
    public static void Main()
    {
        var worker = new System.Threading.Thread(RunAll) { IsBackground = true };
        worker.Start();
        if (worker.Join(2500)) return;
        foreach (string id in Cases) Report(id, "시간 초과(2.5초): 반복이 끝나지 않거나 시간복잡도가 O(n) 을 크게 넘습니다");
        System.Console.Out.Flush();
        System.Environment.Exit(0);
    }

    static string Expect(int[] d, long target, int want)
    {
        int got = ComboAnalyzer.MinHitsToReach(d, target);
        if (got == want) return null;
        string arr = d.Length <= 26 ? "[" + string.Join(",", d) + "]" : "(길이 " + d.Length + ", 모든 값 " + d[0] + ")";
        return "damages=" + arr + ", target=" + target + ": 기대 " + want + " / 결과 " + got;
    }

    // 기준 구현: 모든 시작점에서 합이 target 에 닿을 때까지 더해 본다. O(n^2)
    static int Brute(int[] d, long target)
    {
        int best = 0;
        for (int i = 0; i < d.Length; i++)
        {
            long s = 0;
            for (int j = i; j < d.Length; j++)
            {
                s += d[j];
                if (s >= target) { if (best == 0 || j - i + 1 < best) best = j - i + 1; break; }
            }
        }
        return best;
    }

    static void RunAll()
    {
        Run("empty-and-unreachable", () =>
            Expect(new int[0], 1, 0) ?? Expect(new[] { 1, 2, 3 }, 7, 0) ?? Expect(new[] { 0, 0, 0 }, 1, 0) ?? Expect(new[] { 5 }, 6, 0));

        Run("single-hit-enough", () =>
            Expect(new[] { 5 }, 5, 1) ?? Expect(new[] { 1, 1, 9, 1 }, 8, 1) ?? Expect(new[] { 1, 4, 4 }, 4, 1) ?? Expect(new[] { 3, 1, 1, 7 }, 7, 1));

        Run("basic-window", () =>
            Expect(new[] { 2, 3, 1, 2, 4, 3 }, 7, 2) ?? Expect(new[] { 1, 2, 3, 4, 5 }, 11, 3) ?? Expect(new[] { 4, 1, 1, 1, 2, 3, 5 }, 9, 3));

        Run("whole-array-needed", () =>
            Expect(new[] { 1, 2, 3 }, 6, 3) ?? Expect(new[] { 1, 1, 1, 1 }, 4, 4) ?? Expect(new[] { 2, 2 }, 4, 2));

        Run("zero-damage-hits", () =>
            Expect(new[] { 0, 0, 5, 0, 0, 5, 0 }, 10, 4) ?? Expect(new[] { 0, 3, 0, 0, 3, 0, 3, 3 }, 6, 2) ?? Expect(new[] { 0, 0, 1 }, 1, 1));

        Run("sum-exceeds-int", () =>
            Expect(new[] { 1500000000, 1500000000, 1500000000 }, 4000000000L, 3)
            ?? Expect(new[] { 2000000000, 2000000000, 1 }, 4000000000L, 2)
            ?? Expect(new[] { 2000000000, 2000000000 }, 4000000001L, 0));

        Run("random-vs-bruteforce", () =>
        {
            var rng = new System.Random(31337);
            for (int run = 0; run < 3000; run++)
            {
                int n = rng.Next(0, 25);
                int max = run % 2 == 0 ? 4 : 30;
                var d = new int[n];
                int total = 0;
                for (int i = 0; i < n; i++) { d[i] = rng.Next(0, max); total += d[i]; }
                long target = 1 + rng.Next(0, total + 3);
                string e = Expect(d, target, Brute(d, target));
                if (e != null) return e;
            }
            return null;
        });

        Run("large-linear-time", () =>
        {
            // 40만 타: 시작점마다 처음부터 다시 더하는 O(n^2) 풀이는 제한 시간을 넘는다.
            const int n = 400000;
            var d = new int[n];
            for (int i = 0; i < n; i++) d[i] = 1;
            string e = Expect(d, 200000, 200000) ?? Expect(d, n, n) ?? Expect(d, n + 1L, 0);
            if (e != null) return e;
            for (int i = 0; i < n; i++) d[i] = 1000000000;
            return Expect(d, 250000000000000L, 250000);
        });
    }
}

