using System;

public static class Inventory
{
    // weights[i] >= 1, values[i] >= 0, 두 배열의 길이는 같다. capacity >= 0.
    // 반환: 각 아이템을 최대 한 번씩 골라 무게 합이 capacity 이하일 때 가능한 가치 합의 최댓값.
    public static int MaxValue(int[] weights, int[] values, int capacity)
    {
        // best[w] = 지금까지 본 아이템만으로, 무게 한도 w 에서 얻을 수 있는 최대 가치
        var best = new int[capacity + 1];

        for (int i = 0; i < weights.Length; i++)
        {
            int weight = weights[i];
            int value = values[i];

            // 무게를 큰 쪽에서 작은 쪽으로 돈다.
            // 이때 best[w - weight] 는 아직 "아이템 i 를 넣기 전" 값이므로 i 는 한 번만 쓰인다.
            for (int w = capacity; w >= weight; w--)
            {
                int candidate = best[w - weight] + value;
                if (candidate > best[w]) best[w] = candidate;
            }
        }

        return best[capacity];
    }
}

